/* Inglese — ampliamento Z2: 8 argomenti (L1–L4). */
(function (ST) {
  'use strict';
  const C = ST.content, { mc, fill, order, listen, card } = C;
  const T = (o) => C.addTopic(Object.assign({ subject: 'eng', minutes: 20 }, o));

  /* ---------- L1 ---------- */
  T({ id: 'eng-l1-vocab-work-study', stage: 'L1', prereq: ['eng-l1-vocab-daily'], title: 'Lessico di lavoro e studio', summary: 'Vocabolario ad alta frequenza per ufficio, carriera, università e esami, con collocazioni e false amicizie.',
    objectives: ['Parlare di lavoro: candidature, colloqui, stipendio, orari', 'Parlare di studio: corsi, lezioni, esami, titoli', 'Usare le collocazioni giuste (take an exam, hand in, apply for)'],
    pages: [
      { h: 'Obiettivo', b: 'Lavoro e studio sono tra i temi più frequenti nelle conversazioni e nelle prove di livello B1. Non basta conoscere le parole: serve il **verbo giusto** accanto al nome (*take an exam*, non *make an exam*). Qui impari lessico e collocazioni essenziali.' },
      { h: 'Trovare un lavoro', b: 'Percorso tipico:\n- **apply for** a job: {{en-GB|I’m going to apply for a job at a bank.}}\n- **CV** (UK) / **résumé** (US) e **cover letter** (lettera di presentazione)\n- **interview** (colloquio): {{en-GB|I have a job interview on Monday.}}\n- **be hired** / **get the job**; **be fired** (licenziato) / **resign** (dimettersi)\n\nNota: **job** è numerabile (*a good job*); **work** è non numerabile (*a lot of work*, mai *a work* per «un lavoro»). Anche **career** indica il percorso professionale: *a successful career*.' },
      { h: 'Sul posto di lavoro', b: '- **colleague** / **coworker** = collega; **boss** / **manager** = capo\n- **salary** = stipendio mensile/annuale; **wage** = paga oraria o settimanale; **a pay rise** = aumento\n- **full-time** / **part-time**; **shift** = turno; **overtime** = straordinario\n- **meeting** (riunione), **deadline** (scadenza), **schedule** (programma)\n\n> {{en-GB|I work part-time, so I earn a low salary but I have more free time.}}\n\nCollocazioni: **meet a deadline** (rispettare una scadenza), **be in charge of** (essere responsabile di), **work overtime**, **take a day off**.' },
      { h: 'Studiare', b: '- **school / university / college**: *college* in UK indica spesso un istituto per studenti 16–18, in US l’università.\n- **subject** (materia), **course**, **degree** (laurea), **lecture** (lezione universitaria: *non* «lettura»), **assignment** (compito), **tutor** (docente-guida).\n- **attend** a class = frequentare; **take** a course; **study for** an exam; **do research**.\n\n{{en-GB|I’m doing a degree in engineering and I’m attending lectures every morning.}}\n\n**Learn** si usa per acquisire una competenza, **study** per dedicarsi alla materia: *I study history, I’m learning to drive.*' },
      { h: 'Esami e voti', b: '- **take / sit an exam** (sostenere) ≠ passare: **pass** = superare, **fail** = non superare.\n- **hand in** = consegnare: {{en-GB|Please hand in your essays by Friday.}}\n- **mark** (UK) / **grade** (US) = voto; **get good marks**.\n- **revise** (UK) = ripassare; **cheat** = copiare.\n\n{{en-GB|She passed the exam, but I failed it.}}\n\nAttenzione: *to make an exam* non esiste; in italiano «dare un esame» corrisponde a **take** an exam.' },
      { h: 'Esempio guidato', b: 'Racconto: *«Sono laureato in economia. Ho mandato il CV a molte aziende e ho avuto un colloquio. Ora lavoro a tempo pieno e ho una scadenza importante.»*\n\n→ **I have a degree in economics. I sent my CV to several companies and had an interview. Now I work full-time and I have an important deadline.**\n\nControllo: *have a degree in*, *send a CV*, *have an interview*, *work full-time*.' },
      { h: 'Errori comuni', b: '- *I make an exam* → {{en-GB|I take an exam.}}\n- *I’m looking for a work* → {{en-GB|I’m looking for a job / for work.}}\n- *I read a lecture* (per «una lettura») → {{en-GB|I read a passage / a text.}} (*lecture* = lezione universitaria).\n- *I have 25 years and I work in an office* → {{en-GB|I’m 25 and I work in an office.}}\n- *I pass my holidays* → {{en-GB|I spend my holidays.}}\n- *to assist a lesson* → {{en-GB|to attend a lesson.}}' },
      { h: 'Riepilogo', b: '- apply for a job, have an interview, get the job, resign.\n- salary (fisso), wage (orario), pay rise, part-time, overtime.\n- attend a lecture, take an exam, pass / fail, hand in, revise.\n- job = numerabile; work = non numerabile.\n- meet a deadline, be in charge of.' }
    ],
    exercises: [
      mc('She’s going to ___ for a job at the hospital.', ['make', 'apply', 'ask', 'try'], 1),
      mc('I have to ___ my essay in by Friday.', ['give', 'put', 'hand', 'carry'], 2),
      mc('Which sentence is correct?', ['I’m looking for a work.', 'I’m looking for work.', 'I’m looking for works.', 'I’m looking a work.'], 1),
      fill('Complete: He studied hard and ___ his driving test. (superare)', ['passed'], 'Pass = superare.'),
      mc('A person who works for the same company as you is your…', ['colleague', 'tutor', 'customer', 'competitor'], 0),
      order('Metti in ordine', ['We', 'must', 'meet', 'the', 'deadline'], 'Collocazione: meet a deadline.'),
      listen('I’m on a part-time contract, so I only work three days a week.', 'en-GB', 'How many days a week does the speaker work?', ['Five', 'Two', 'Four', 'Three'], 3, 'Part-time: tre giorni.'),
      mc('«Wage» usually means…', ['a monthly fixed salary', 'pay for hours worked', 'a job interview', 'a tax'], 1)
    ],
    test: [
      mc('Which verb collocates with «an exam» in the sense of «sostenere»?', ['do a test of', 'make', 'take', 'pass out'], 2),
      mc('A ___ is a talk given to a large group of university students.', ['lecture', 'reading', 'library', 'lesson plan'], 0),
      mc('Choose the correct sentence.', ['I have 30 years and I work in a bank.', 'I am 30 and I work in a bank.', 'I have 30 and I work in a bank.', 'I am 30 years and work in bank.'], 1),
      mc('If you leave your job by your own choice, you…', ['are fired', 'are hired', 'resign', 'attend'], 2),
      fill('Complete: I’m in ___ of the sales team. (responsabile)', ['charge'], 'Be in charge of.')
    ],
    cards: [card('c1', 'candidarsi a', 'apply for', 'I applied for three jobs.'), card('c2', 'colloquio', 'interview', 'a job interview'), card('c3', 'stipendio', 'salary', 'a good salary'), card('c4', 'scadenza', 'deadline', 'a tight deadline'),
      card('c5', 'collega', 'colleague', 'my colleagues'), card('c6', 'consegnare', 'hand in', 'Hand in your homework.'), card('c7', 'laurea', 'degree', 'a degree in law'), card('c8', 'superare (esame)', 'pass', 'I passed the exam.'), card('c9', 'frequentare', 'attend', 'attend a lecture'), card('c10', 'dimettersi', 'resign', 'She resigned last week.')],
    listening: [{ id: 'l1', lang: 'en-GB', title: 'A new job', text: 'Last month I applied for a job at a language school, and last week I had an interview. It went well, and yesterday they phoned to say I got the job. I’m going to work part-time, three days a week, which suits me because I’m also doing a degree in education. The salary isn’t high, but my colleagues seem friendly. The only problem is that I have to hand in a big assignment next Friday, so I’ll be busy.',
      qs: [{ q: 'When did the speaker have the interview?', o: ['Last week', 'Last month', 'Yesterday', 'Next Friday'], a: 0, kind: 'explicit' }, { q: 'Why does part-time work suit the speaker?', o: ['She is also studying for a degree', 'She dislikes the school', 'She has a baby', 'She lives abroad'], a: 0, kind: 'explicit' }, { q: 'How does the speaker feel about the new job?', o: ['Fairly positive, but a little worried about time', 'Very unhappy', 'Angry about the pay', 'Completely relaxed'], a: 0, kind: 'implicit' }] }],
    dictation: [{ text: 'I have a job interview on Monday morning.', lang: 'en-GB' }, { text: 'Please hand in your essays by Friday.', lang: 'en-US' }, { text: 'She passed the exam but I failed it.', lang: 'en-AU' }],
    shadowing: [{ text: 'I’m applying for a job at a bank.', lang: 'en-GB', tip: 'Applying: accento su -PLY-; for debole /fə/.' }, { text: 'We have to meet the deadline.', lang: 'en-US', tip: 'DEADline: accento sulla prima sillaba.' }, { text: 'I work part-time and study in the evenings.', lang: 'en-AU', tip: 'Accenta part-time, study, evenings.' }],
    speaking: [{ prompt: 'Talk about your job or studies: what you do, where, and one thing you like or dislike.', model: 'I work full-time in an office. I’m in charge of the orders, and I usually have a lot of deadlines. I like my colleagues, but I don’t like working overtime.' }, { prompt: 'Describe a job interview or an exam you have taken.', model: 'Last year I took an English exam. I studied for three weeks, and I passed it. I was nervous at the beginning, but the examiner was friendly.' }] });

  T({ id: 'eng-l1-vocab-health-travel', stage: 'L1', prereq: ['eng-l1-vocab-daily'], title: 'Lessico di salute e viaggi', summary: 'Parole e frasi per dal medico, in farmacia, in aeroporto, in hotel e in viaggio.',
    objectives: ['Descrivere sintomi e chiedere aiuto medico', 'Usare il lessico di biglietti, aeroporto e alloggio', 'Evitare gli errori con nomi non numerabili (luggage, advice, information)'],
    pages: [
      { h: 'Obiettivo', b: 'In viaggio e quando si sta male l’inglese serve subito. Questa lezione ti dà le **frasi chiave** per salute e viaggi, con attenzione ai nomi **non numerabili** (*luggage, advice, information*) che in italiano sono invece numerabili.' },
      { h: 'Dire come stai', b: '- **I have a headache / a sore throat / a cold / a fever / a stomach ache.** (*have + nome*)\n- **My back hurts / My leg is sore.** (*hurt / be sore*)\n- **I feel sick** (ho la nausea) / **I’m ill** (UK: sono malato) / **I feel dizzy** (mi gira la testa).\n- **I’ve got a temperature.** (ho la febbre)\n\n> {{en-GB|I’ve got a sore throat and a temperature, so I’m staying at home.}}\n\n*Ill* e *sick* sono simili; *sick* in UK indica spesso la nausea.' },
      { h: 'Dal medico e in farmacia', b: '- **doctor / GP** (medico di base), **nurse**, **patient**, **appointment**\n- **prescription** = ricetta; **medicine** = farmaco; **pills / tablets**; **painkiller** = antidolorifico\n- **pharmacy / chemist’s** (UK)\n- **symptoms** (sintomi), **injury**, **allergy**, **recover** (guarire).\n\n{{en-GB|I’d like to make an appointment to see the doctor.}}\n{{en-GB|You should rest and drink plenty of water.}}\n\nAttenzione: **advice** è non numerabile: *some advice*, *a piece of advice*; mai *advices*.' },
      { h: 'Biglietti e trasporti', b: '- **single ticket** (andata) / **return ticket** (andata e ritorno)\n- **fare** = costo del biglietto; **platform** = binario; **departure / arrival**\n- **delayed** (in ritardo), **cancelled**\n- **on the train / on the bus / on the plane**, ma **in a taxi / in a car**\n\n{{en-GB|A return ticket to Manchester, please.}}\n{{en-GB|The train has been delayed by twenty minutes.}}\n\n**Journey / trip / travel**: *journey* = il viaggio in sé (spostamento), *trip* = gita o viaggio breve con ritorno; **travel** è non numerabile: *Travel is fun*, ma *a long journey*, *a business trip*.' },
      { h: 'Aeroporto e hotel', b: '- **check in**, **boarding pass**, **gate**, **customs**, **passport control**\n- **luggage / baggage** (non numerabile): {{en-GB|I have two pieces of luggage.}}\n- **book a room**, **reception**, **single/double room**, **accommodation** (non numerabile), **sightseeing**\n- **check in / check out** all’hotel.\n\n{{en-GB|I’d like to book a double room for two nights, please.}}\n\nPer chiedere: *Could you tell me where the check-in desk is?* / *Is breakfast included?*' },
      { h: 'Esempio guidato', b: 'Situazione: *«Hai mal di gola, vuoi un appuntamento dal medico e poi parti per un viaggio di lavoro. Ti serve un biglietto di sola andata.»*\n\n→ **I have a sore throat. I’d like to make an appointment. Then I’m going on a business trip and I need a single ticket.**\n\nControllo: *have a sore throat*, *make an appointment*, *business trip*, *single ticket*.' },
      { h: 'Errori comuni', b: '- *I have pain to the head* → {{en-GB|I have a headache.}}\n- *my luggages* → {{en-GB|my luggage.}}\n- *some informations* → {{en-GB|some information.}}\n- *He gave me an advice* → {{en-GB|He gave me some advice.}}\n- *I made a trip by the train* → {{en-GB|I went on a trip by train.}}\n- *I’m in the bus* → {{en-GB|I’m on the bus.}}\n- *travels* come nome astratto → {{en-GB|travel / trips.}}' },
      { h: 'Riepilogo', b: '- have + headache / sore throat / cold / temperature.\n- prescription, painkiller, appointment, recover.\n- single / return ticket, platform, delayed, fare.\n- luggage, advice, information, accommodation = non numerabili.\n- on the bus / train / plane; in a car / taxi.' }
    ],
    exercises: [
      mc('I can’t go to work. I have a terrible ___.', ['stomach pain to', 'headache', 'head pain of', 'pain headache'], 1),
      mc('Which sentence is correct?', ['I have three luggages.', 'I have three luggage.', 'I have three pieces of luggage.', 'I have three luggage pieces of.'], 2),
      mc('A ticket that lets you travel there and back is a…', ['single ticket', 'return ticket', 'boarding pass', 'platform'], 1),
      fill('Complete: He gave me some good ___. (consiglio)', ['advice'], 'Advice è non numerabile.'),
      mc('We travelled to Rome ___ train.', ['with the', 'on the', 'by', 'in the'], 2, 'By train = con il treno (mezzo in generale).'),
      order('Metti in ordine', ['I’d', 'like', 'to', 'book', 'a', 'room'], 'Frase di richiesta cortese.'),
      listen('The doctor told me to rest and take these tablets twice a day.', 'en-GB', 'What must the speaker do?', ['Go to hospital', 'Rest and take tablets', 'Stop work for a year', 'Buy a new phone'], 1, 'Rest + tablets.'),
      mc('Where do you wait for a train?', ['at the platform', 'at the gate', 'at the fare', 'at the check-in'], 0)
    ],
    test: [
      mc('Which is a non-countable noun?', ['trip', 'journey', 'information', 'ticket'], 2),
      mc('A ___ is a note from the doctor to get medicine.', ['symptom', 'prescription', 'allergy', 'injury'], 1),
      mc('Choose the correct sentence.', ['I’m on the bus.', 'I’m in the bus.', 'I’m at the bus.', 'I’m by the bus.'], 0),
      mc('«The flight was delayed» means…', ['It was cancelled.', 'It left early.', 'It left late.', 'It was full.'], 2),
      fill('Complete: I’m going on a business ___ next week. (viaggio breve)', ['trip'], 'Trip = viaggio con ritorno.')
    ],
    cards: [card('c1', 'mal di testa', 'headache', 'I have a headache.'), card('c2', 'mal di gola', 'sore throat', 'a sore throat'), card('c3', 'ricetta (medica)', 'prescription', 'a prescription for antibiotics'), card('c4', 'bagaglio', 'luggage', 'My luggage is heavy.'),
      card('c5', 'binario', 'platform', 'Platform 5'), card('c6', 'andata e ritorno', 'return ticket', 'a return to Leeds'), card('c7', 'in ritardo', 'delayed', 'The flight is delayed.'), card('c8', 'prenotare', 'to book', 'I booked a room.'), card('c9', 'guarire', 'to recover', 'He recovered quickly.'), card('c10', 'alloggio', 'accommodation', 'cheap accommodation')],
    listening: [{ id: 'l1', lang: 'en-US', title: 'Before the trip', text: 'I was supposed to fly to Boston on Friday, but I woke up with a sore throat and a temperature. I went to the doctor, who gave me a prescription and some advice: rest, drink a lot of water and don’t travel for three days. I called the airline, and they changed my ticket to Monday without extra charge. Now I’m at home, taking my medicine, and I’ve already packed my luggage, so I’m ready to go.',
      qs: [{ q: 'Why did the speaker go to the doctor?', o: ['She had a sore throat and a temperature', 'She lost her luggage', 'She missed her flight', 'She wanted a prescription for a friend'], a: 0, kind: 'explicit' }, { q: 'When will she travel now?', o: ['On Monday', 'On Friday', 'In three weeks', 'She won’t travel'], a: 0, kind: 'explicit' }, { q: 'How does the speaker feel at the end?', o: ['Better and prepared', 'Very angry at the airline', 'Worried about the money', 'Too ill to speak'], a: 0, kind: 'implicit' }] }],
    dictation: [{ text: 'I have a sore throat and a temperature.', lang: 'en-GB' }, { text: 'A return ticket to Manchester, please.', lang: 'en-US' }, { text: 'The train has been delayed by twenty minutes.', lang: 'en-AU' }],
    shadowing: [{ text: 'I’d like to make an appointment to see the doctor.', lang: 'en-GB', tip: 'apPOINTment: accento sulla seconda sillaba.' }, { text: 'Could you tell me where the check-in desk is?', lang: 'en-US', tip: 'Intonazione discendente sulla domanda indiretta.' }, { text: 'I’m staying in a small hotel near the station.', lang: 'en-AU', tip: 'hoTEL: accento sulla seconda sillaba.' }],
    speaking: [{ prompt: 'You feel ill. Phone the clinic and explain your symptoms.', model: 'Hello, I’d like to make an appointment, please. I have a sore throat and a headache, and I’ve got a temperature. It started yesterday evening.' }, { prompt: 'Tell a friend about a recent trip: transport, accommodation and one problem.', model: 'Last month I went on a trip to Edinburgh. I travelled by train, and I stayed in a small hotel. The train was delayed by an hour, but the journey was nice.' }] });

  /* ---------- L2 ---------- */
  T({ id: 'eng-l2-false-friends-italian', stage: 'L2', prereq: ['eng-l2-articles'], title: 'False amicizie e errori tipici degli italiani', summary: 'Parole ingannevoli (actually, eventually, library…) e gli errori più frequenti di chi parla italiano.',
    objectives: ['Riconoscere le false amicizie più frequenti tra italiano e inglese', 'Evitare i calchi grammaticali tipici (I am agree, since 3 years)', 'Autocorreggersi con una breve lista di controllo'],
    pages: [
      { h: 'Obiettivo', b: 'Molte parole inglesi **sembrano** italiane ma hanno un altro significato: sono i **false friends**. Altri errori nascono dal tradurre la struttura italiana parola per parola. Conoscere i casi più frequenti ti fa evitare gli errori «da italiano» che un madrelingua nota subito.' },
      { h: 'Parole ingannevoli (1)', b: '- **actually** = in realtà (non «attualmente», che è *currently*): {{en-GB|Actually, I’m not Italian, I’m Swiss.}}\n- **eventually** = alla fine (non «eventualmente», che è *possibly*): {{en-GB|Eventually, we found the hotel.}}\n- **sympathetic** = comprensivo (non «simpatico», che è *nice / friendly*): {{en-GB|She was very sympathetic when I lost my job.}}\n- **library** = biblioteca (la libreria è *bookshop*): {{en-GB|I borrowed this book from the library.}}\n- **parents** = genitori (i parenti sono *relatives*).\n- **college** = istituto di istruzione, non «collegio».' },
      { h: 'Parole ingannevoli (2)', b: '- **argument** = litigio (anche «argomentazione»), non «argomento» (*topic / subject*): {{en-GB|We had an argument about money.}}\n- **fabric** = tessuto; la fabbrica è *factory*.\n- **pretend** = fingere (non «pretendere», che è *expect / demand*): {{en-GB|He pretended to be asleep.}}\n- **attend** = frequentare/partecipare; «attendere» è *wait for*.\n- **educated** = istruito; «educato» è *polite*.\n- **magazine** = rivista; «magazzino» è *warehouse*.\n- **camera** = macchina fotografica; «camera» è *room*.\n- **sensible** = ragionevole; «sensibile» è *sensitive*.' },
      { h: 'Errori grammaticali tipici', b: '- **I am agree** → {{en-GB|I agree.}} (*agree* è un verbo, non un aggettivo).\n- **I have 20 years** → {{en-GB|I am 20.}}\n- **I live here since 2020** → {{en-GB|I have lived here since 2020.}}\n- **since three years** → {{en-GB|for three years.}} (*for* = durata, *since* = inizio)\n- **People is** → {{en-GB|People are.}} (plurale)\n- **The informations / the news are** → {{en-GB|The information is… / The news is…}}\n- **Depend of** → {{en-GB|depend on.}}\n- **Discuss about** → {{en-GB|discuss it / argue about.}}' },
      { h: 'Verbi e strutture', b: '- **make a photo** → {{en-GB|take a photo.}}\n- **make a trip / a walk** → {{en-GB|go on a trip / go for a walk.}}\n- **I want that you come** → {{en-GB|I want you to come.}}\n- **explain me** → {{en-GB|explain it to me.}}\n- **I must to go** → {{en-GB|I must go.}} (modali senza *to*)\n- **I like very much pizza** → {{en-GB|I like pizza very much.}} (l’oggetto subito dopo il verbo)\n- **Is raining** → {{en-GB|It’s raining.}} (soggetto obbligatorio)' },
      { h: 'Articoli e preposizioni', b: 'L’italiano usa l’articolo dove l’inglese non lo usa:\n- **The life is hard** → {{en-GB|Life is hard.}}\n- **I like the music** (in generale) → {{en-GB|I like music.}}\n- **She is teacher** → {{en-GB|She is a teacher.}} (con le professioni l’articolo serve)\n- **at the university / at home** → {{en-GB|at university / at home.}} (stato in luogo istituzionale)\n- **in the 2020** → {{en-GB|in 2020.}}' },
      { h: 'Esempio guidato', b: 'Correggi: *«I am agree with you. I live here since three years and I like very much the life in this city. The people is friendly.»*\n\n→ **I agree with you. I have lived here for three years and I like life in this city very much. The people are friendly.**\n\nControllo: *agree*, *have lived … for*, *like … very much*, *life* senza articolo, *people are*.' },
      { h: 'Riepilogo', b: '- actually ≠ attualmente; eventually ≠ eventualmente; library ≠ libreria; sympathetic ≠ simpatico.\n- I agree; I am 20; I have lived here for three years.\n- people are; news / information = singolare e non numerabile.\n- take a photo; depend on; explain it to me; I like it very much.\n- Niente articolo per concetti generali (*life, music*).' }
    ],
    exercises: [
      mc('«Eventually, we found the hotel.» means…', ['Possibly we found it.', 'In the end we found it.', 'Immediately we found it.', 'We never found it.'], 1),
      mc('Which sentence is correct?', ['I am agree with you.', 'I agree with you.', 'I agree to you.', 'I’m agreeing you.'], 1),
      mc('The Italian «libreria» is…', ['library', 'bookshop', 'bookcase only', 'school'], 1),
      fill('Complete: I’ve lived here ___ three years. (for / since)', ['for'], 'For + durata.'),
      mc('My teacher is very ___: she always listens and understands my problems.', ['sensible', 'sympathetic', 'pretended', 'educated'], 1),
      order('Metti in ordine', ['I', 'like', 'pizza', 'very', 'much'], 'L’oggetto resta subito dopo il verbo.'),
      listen('I’m not working in Rome at the moment. Actually, I’m living in Milan now.', 'en-GB', 'Where is the speaker living now?', ['Rome', 'Milan', 'Naples', 'London'], 1, 'Actually = in realtà.'),
      mc('A person who is polite is…', ['educated', 'polite', 'educative', 'educating'], 1)
    ],
    test: [
      mc('Choose the correct request.', ['Can you give me some informations?', 'Can you give me some information?', 'Can you give me an information?', 'Can you give me informations?'], 1),
      mc('«Currently» is the English for the Italian…', ['eventualmente', 'attualmente', 'effettivamente', 'precisamente'], 1),
      mc('Which sentence about age is correct?', ['My sister has 25 years.', 'My sister is 25 years.', 'My sister is 25.', 'My sister has 25.'], 2),
      mc('Which sentence uses the right preposition?', ['It depends of the weather.', 'It depends on the weather.', 'It depends from the weather.', 'It is depending the weather.'], 1),
      fill('Complete: Let’s ___ a photo of the group. (scattare)', ['take'], 'Take a photo.')
    ],
    cards: [card('c1', 'in realtà', 'actually', 'Actually, I disagree.'), card('c2', 'alla fine', 'eventually', 'Eventually, he left.'), card('c3', 'comprensivo', 'sympathetic', 'a sympathetic teacher'), card('c4', 'biblioteca', 'library', 'the city library'),
      card('c5', 'parenti', 'relatives', 'I visit my relatives.'), card('c6', 'fingere', 'to pretend', 'He pretended to sleep.'), card('c7', 'litigio', 'argument', 'a big argument'), card('c8', 'ragionevole', 'sensible', 'a sensible decision'), card('c9', 'attualmente', 'currently', 'I’m currently working.'), card('c10', 'educato', 'polite', 'a polite boy')],
    listening: [{ id: 'l1', lang: 'en-GB', title: 'A misunderstanding', text: 'When I started learning English, I made a lot of mistakes. Once I told my boss that I was currently excited to “assist” the meeting, but I really meant that I wanted to attend it. Another time I said, “I am agree with you”, and he smiled. Actually, I now laugh at these mistakes. Eventually I learned to check my sentences: I ask myself if a word only looks Italian. My boss was very sympathetic, and he never made me feel stupid.',
      qs: [{ q: 'What did the speaker want to say about the meeting?', o: ['That he wanted to attend it', 'That he wanted to help in it', 'That he wanted to cancel it', 'That he wanted to chair it'], a: 0, kind: 'explicit' }, { q: 'What does the speaker do now?', o: ['Checks whether a word only looks Italian', 'Avoids speaking', 'Translates word for word', 'Writes everything twice'], a: 0, kind: 'explicit' }, { q: 'What does the speaker say about his boss?', o: ['He was understanding', 'He was angry', 'He was a teacher', 'He was Italian'], a: 0, kind: 'implicit' }] }],
    dictation: [{ text: 'Actually, I am not Italian, I am Swiss.', lang: 'en-GB' }, { text: 'I have lived here for three years.', lang: 'en-US' }, { text: 'She borrowed the book from the library.', lang: 'en-AU' }],
    shadowing: [{ text: 'Actually, I think you’re right.', lang: 'en-GB', tip: 'ACtually: accento sulla prima sillaba.' }, { text: 'I’ve lived here for three years.', lang: 'en-US', tip: 'I’ve /aɪv/; for debole /fə/.' }, { text: 'She was very sympathetic about my problem.', lang: 'en-AU', tip: 'sympaTHEtic: accento sulla terza sillaba.' }],
    speaking: [{ prompt: 'Say three sentences using actually, eventually and library correctly.', model: 'Actually, I don’t live in the city centre. Eventually I found a flat near the river. There’s a big library not far from my house.' }, { prompt: 'Correct and say aloud: «I am agree, I have 30 years and I live here since 2019.»', model: 'I agree. I am 30 and I have lived here since 2019.' }] });

  T({ id: 'eng-l2-prepositions-time-place-review', stage: 'L2', prereq: ['eng-l0-prepositions'], title: 'Preposizioni di tempo e luogo: ripasso e casi difficili', summary: 'in/on/at, for/since/during, by/until, in/within e i casi di luogo che confondono (arrive in/at, on the bus, in hospital).',
    objectives: ['Scegliere con sicurezza in, on, at per tempo e luogo', 'Distinguere for / since / during e by / until', 'Usare le espressioni fisse (in time, on time, at the end, in the end)'],
    pages: [
      { h: 'Obiettivo', b: 'Le preposizioni sono il punto più «arbitrario» dell’inglese: spesso non si traducono una per una. Qui ripassi le regole di base e le **coppie confondibili**, con tante espressioni fisse. Per ripassare le basi guarda la lezione sulle preposizioni di livello A2.' },
      { h: 'In, on, at nel tempo', b: '- **at** + punto preciso: *at 5 o’clock, at noon, at night, at the weekend* (UK)\n- **on** + giorni e date: *on Monday, on 5 May, on Friday evening, on my birthday*\n- **in** + periodi: *in July, in 2024, in the morning, in the summer, in the 21st century*\n\n{{en-GB|The meeting is on Tuesday at nine in the morning.}}\n\nNota: *in the morning* ma **on Monday morning**. Niente preposizione con *next, last, this, every*: *I’ll see you next week* (non *in next week*).' },
      { h: 'For, since, during, while', b: '- **for** + durata: {{en-GB|I’ve lived here for six years.}}\n- **since** + inizio: {{en-GB|I’ve lived here since 2019.}}\n- **during** + nome (evento): {{en-GB|I fell asleep during the film.}}\n- **while** + frase: {{en-GB|I fell asleep while I was watching the film.}}\n- **ago** = fa: *three years ago*.\n\n**Mai** *since three years*. Per la durata con il present perfect: *for* + periodo, *since* + punto d’inizio.' },
      { h: 'By, until, in, within', b: '- **by** = entro (limite): {{en-GB|Please send it by Friday.}} (venerdì è l’ultimo momento)\n- **until / till** = fino a (durata): {{en-GB|I’ll wait until Friday.}} (aspetto per tutto il tempo fino a venerdì)\n- **in two weeks** = tra due settimane: {{en-GB|The shop will open in two weeks.}}\n- **within two weeks** = entro due settimane: {{en-GB|We’ll reply within two weeks.}}\n\nEspressioni fisse: **on time** (puntuale) / **in time** (in tempo utile): {{en-GB|We arrived in time for the film, and the film started on time.}}; **at the end** (alla fine di qualcosa) / **in the end** (alla fine, infine): {{en-GB|In the end, we bought the red car.}}' },
      { h: 'In, on, at nel luogo', b: '- **at** = punto: *at the station, at the door, at home, at work, at the corner*\n- **in** = spazio chiuso o ampio: *in a room, in London, in the car, in bed, in hospital (UK)*\n- **on** = superficie/linea: *on the table, on the wall, on the second floor, on the bus / train / plane*\n\n{{en-GB|He’s at the supermarket. She’s in the kitchen. The keys are on the shelf.}}\n\n**in a car / taxi**, ma **on a bus / train / bike**. *At university* (studiare), *in the university* (nell’edificio).' },
      { h: 'Casi difficili di luogo e movimento', b: '- **arrive in** + città/paese; **arrive at** + luogo specifico: {{en-GB|We arrived in Rome at the station at six.}}\n- **between** (due) / **among** (più di due): {{en-GB|He sat between Anna and Tom. / She’s among the best students.}}\n- **next to / beside / by** = accanto; **opposite** = di fronte; **across** = dall’altra parte / attraverso; **through** = attraverso (un volume): *through the tunnel*.\n- **over / above** = sopra; **under / below** = sotto.\n- **get in / out of** (car), **get on / off** (bus, train).' },
      { h: 'Esempio guidato', b: 'Correggi: *«I arrived to Rome in Monday at 8 in the morning. I stayed there since a week and I left until Sunday.»*\n\n→ **I arrived in Rome on Monday at 8 in the morning. I stayed there for a week and I left on Sunday.**\n\nControllo: *arrive in*, *on Monday*, *for a week* (durata), *on Sunday*. Nota: *I left by Sunday* significherebbe «entro domenica».' },
      { h: 'Errori comuni', b: '- *arrive to Paris* → {{en-GB|arrive in Paris.}}\n- *in Monday* → {{en-GB|on Monday.}}\n- *at the morning* → {{en-GB|in the morning.}}\n- *I work here since 2020* → {{en-GB|I have worked here since 2020.}}\n- *I’m on the car* → {{en-GB|I’m in the car.}}\n- *married with* → {{en-GB|married to.}}\n- *different than/of* → {{en-GB|different from (UK).}}\n- *at the end I decided* (per «alla fine, infine») → {{en-GB|In the end I decided.}}' },
      { h: 'Riepilogo', b: '- at (ora), on (giorno/data), in (mese/anno/parte del giorno).\n- for (durata), since (inizio), during + nome, while + frase.\n- by = entro, until = fino a; in = tra, within = entro.\n- at (punto), in (spazio), on (superficie, mezzi pubblici).\n- arrive in + città, arrive at + luogo.' }
    ],
    exercises: [
      mc('The meeting is ___ Thursday.', ['in', 'at', 'on', 'by'], 2),
      mc('We’ve known each other ___ 2018.', ['for', 'since', 'during', 'from since'], 1),
      mc('Please send me the report ___ Friday. (not later than Friday)', ['until', 'by', 'in', 'on'], 1),
      fill('Complete: We arrived ___ Berlin at 6 p.m. (arrive + città)', ['in'], 'Arrive in + città.'),
      mc('I fell asleep ___ the lecture.', ['while', 'during', 'for', 'since'], 1),
      order('Metti in ordine', ['She', 'sat', 'between', 'her', 'two', 'friends'], 'Between = tra due.'),
      listen('I’ll be in the office until six, and I’ll call you by Friday.', 'en-GB', 'What will the speaker do by Friday?', ['Stay in the office', 'Call you', 'Leave for Rome', 'Send an email'], 1, 'By Friday = entro venerdì.'),
      mc('You travel ___ a bus, but ___ a taxi.', ['on / in', 'in / on', 'at / by', 'by / on'], 0)
    ],
    test: [
      mc('Which sentence is correct?', ['I live here since three years.', 'I have lived here for three years.', 'I have lived here since three years.', 'I live here during three years.'], 1),
      mc('«I’ll see you ___ week.»', ['in next', 'at next', 'next', 'on next'], 2),
      mc('Which is correct?', ['We’ll reply in two weeks, not later.', 'We’ll reply within two weeks.', 'We’ll reply until two weeks.', 'We’ll reply during two weeks.'], 1),
      mc('«In the end» means…', ['at the finish of something', 'finally, after all', 'at the edge', 'in the evening'], 1),
      fill('Complete: The film starts at eight, so please arrive ___ time. (puntuale, in tempo utile per iniziare insieme: in/on)', ['on'], 'On time = puntuale.')
    ],
    cards: [card('c1', 'entro (limite)', 'by', 'by Friday'), card('c2', 'fino a', 'until', 'until six'), card('c3', 'durante', 'during', 'during the film'), card('c4', 'puntuale', 'on time', 'The train was on time.'),
      card('c5', 'in tempo utile', 'in time', 'We got there in time.'), card('c6', 'alla fine (infine)', 'in the end', 'In the end, we won.'), card('c7', 'tra (due)', 'between', 'between us'), card('c8', 'tra (molti)', 'among', 'among friends'), card('c9', 'di fronte a', 'opposite', 'opposite the bank'), card('c10', 'sposato con', 'married to', 'married to a teacher')],
    listening: [{ id: 'l1', lang: 'en-AU', title: 'Planning the week', text: 'Right, let’s plan the week. The team meeting is on Tuesday at ten, so please arrive on time. I’ll be away from Wednesday until Friday, so send me your reports by Tuesday evening. During my absence, Sara will be in charge. The new colleague starts in two weeks, and we’ll organise a welcome lunch within a month. Oh, and the lunch will be at the restaurant opposite the station.',
      qs: [{ q: 'When is the team meeting?', o: ['On Tuesday at ten', 'On Wednesday at ten', 'On Friday morning', 'At the weekend'], a: 0, kind: 'explicit' }, { q: 'By when should reports be sent?', o: ['By Tuesday evening', 'Until Friday', 'Within a month', 'In two weeks'], a: 0, kind: 'explicit' }, { q: 'Who will be responsible while the speaker is away?', o: ['Sara', 'The new colleague', 'The speaker', 'Nobody'], a: 0, kind: 'implicit' }] }],
    dictation: [{ text: 'The meeting is on Tuesday at ten in the morning.', lang: 'en-GB' }, { text: 'I have lived in Boston since 2019.', lang: 'en-US' }, { text: 'Please send me the report by Friday.', lang: 'en-AU' }],
    shadowing: [{ text: 'We arrived in London at six in the evening.', lang: 'en-GB', tip: 'In e at: forme deboli, quasi /ɪn/ e /ət/.' }, { text: 'I’ve been waiting for an hour.', lang: 'en-US', tip: 'For debole /fər/.' }, { text: 'The shop is opposite the station.', lang: 'en-AU', tip: 'OPposite: accento sulla prima sillaba.' }],
    speaking: [{ prompt: 'Describe your week using on, at, in and by.', model: 'On Monday I start work at nine. In the afternoon I have a meeting, and I have to finish a report by Wednesday. At the weekend I usually go to the beach.' }, { prompt: 'Say how long you have lived in your town, and where your home is.', model: 'I’ve lived in my town for ten years, since 2016. My flat is on the second floor, opposite a small park.' }] });

  /* ---------- L3 ---------- */
  T({ id: 'eng-l3-vocab-society-economy', stage: 'L3', prereq: ['eng-l2-word-formation'], title: 'Lessico B2: società ed economia', summary: 'Parole e collocazioni per parlare di disuguaglianze, lavoro, tasse, crescita, immigrazione e servizi pubblici.',
    objectives: ['Usare lessico astratto di società ed economia con le collocazioni giuste', 'Distinguere parole simili (economic/economical, policy/politics)', 'Commentare un problema sociale con verbi e nomi precisi'],
    pages: [
      { h: 'Obiettivo', b: 'Al livello B2 si discute di temi sociali ed economici: lavoro, disuguaglianza, welfare, crescita. Servono **nomi astratti**, **aggettivi precisi** e le **collocazioni** (*tackle poverty, boost the economy*). In questa lezione costruisci un lessico di base per discutere e scrivere.' },
      { h: 'Economia e lavoro', b: '- **the economy** = economia; **economic growth** = crescita; **recession** = recessione; **inflation**\n- **unemployment** (disoccupazione) / **employment**; **the workforce** = forza lavoro; **minimum wage**\n- **income** = reddito; **cost of living**; **household** = nucleo familiare\n- **tax / taxation**; **budget**; **debt**; **public spending**\n\n{{en-GB|Unemployment has risen sharply since the recession.}}\n{{en-GB|The government plans to cut public spending and raise taxes.}}\n\nCollocazioni: **boost the economy**, **create jobs**, **cut spending**, **a fall / rise in unemployment**.' },
      { h: 'Società e disuguaglianze', b: '- **inequality** / **the gap between rich and poor**; **poverty**; **homelessness**\n- **welfare** (assistenza sociale), **benefits** (sussidi), **pension**, **public services**\n- **immigration / immigrants**, **integration**, **community**\n- **an ageing population** = popolazione che invecchia\n- **housing** (alloggi): *affordable housing*.\n\n{{en-GB|The gap between rich and poor is growing.}}\n{{en-GB|Many people can’t afford to buy a house.}}\n\nCollocazioni: **tackle / reduce poverty**, **close the gap**, **provide support**, **raise awareness**.' },
      { h: 'Parole simili da distinguere', b: '- **economic** (relativo all’economia) / **economical** (conveniente, che fa risparmiare): {{en-GB|an economic crisis}} / {{en-GB|an economical car}}\n- **policy** (linea politica, regola) / **politics** (la politica come attività): {{en-GB|The government’s new housing policy…}} / {{en-GB|He’s interested in politics.}}\n- **society** (la società in generale) / **company** (azienda)\n- **efficient** (che funziona bene) / **effective** (che dà il risultato voluto)\n- **rise** (intransitivo: *prices rise*) / **raise** (transitivo: *raise taxes*)\n- **fewer + numerabile / less + non numerabile**: *fewer jobs, less money*.' },
      { h: 'Descrivere cambiamenti', b: '- Aumento: **rise, increase, grow, go up**\n- Calo: **fall, decrease, decline, drop**\n- Stabilità: **remain stable / unchanged**\n- Intensità: **sharply, steadily, slightly, dramatically**\n\n{{en-GB|The cost of living has increased steadily over the last decade.}}\n{{en-GB|There has been a sharp fall in the number of young people leaving the country.}}\n\nNota: **a rise in** / **an increase in** + nome: *a rise in prices* (non *of*).' },
      { h: 'Esempio guidato', b: 'Idea: *«In molti paesi il costo della vita aumenta e i giovani non possono permettersi un alloggio.»*\n\n→ **In many countries the cost of living is rising, and young people can’t afford housing.**\n\nVersione B2 più ricca: **In many countries, the rising cost of living has made affordable housing a major problem for young people.**\n\nControllo: *rising cost of living*, *affordable housing*, *major problem*.' },
      { h: 'Errori comuni', b: '- *an economical crisis* → {{en-GB|an economic crisis.}}\n- *the politics of the government* (per «le linee») → {{en-GB|the government’s policy.}}\n- *the unemployment is high* → {{en-GB|unemployment is high.}} (senza articolo in generale)\n- *an increase of prices* → {{en-GB|an increase in prices.}}\n- *The society needs…* → {{en-GB|Society needs…}}\n- *less jobs* → {{en-GB|fewer jobs.}}\n- *people are… the poors* → {{en-GB|the poor.}} (aggettivo sostantivato, senza -s)' },
      { h: 'Riepilogo', b: '- economy, growth, recession, inflation, tax, budget, debt.\n- inequality, poverty, welfare, benefits, ageing population.\n- economic ≠ economical; policy ≠ politics; effective ≠ efficient.\n- a rise / fall in + nome; rise (intr.) / raise (tr.).\n- tackle poverty, boost the economy, create jobs.' }
    ],
    exercises: [
      mc('The government wants to ___ the economy by investing in transport.', ['rise', 'boost', 'fall', 'reduce'], 1),
      mc('There has been a sharp rise ___ prices.', ['of', 'for', 'in', 'at'], 2),
      mc('Which adjective means «che fa risparmiare»?', ['economic', 'economical', 'economy', 'economist'], 1),
      fill('Complete: There are ___ jobs than ten years ago. (meno, numerabile)', ['fewer'], 'Fewer + nome numerabile.'),
      mc('A government’s plan for how to deal with an issue is its…', ['policy', 'politics', 'politician', 'police'], 0),
      order('Metti in ordine', ['The', 'gap', 'between', 'rich', 'and', 'poor', 'is', 'growing'], 'Soggetto + is growing: present continuous.'),
      listen('Unemployment among young people has fallen slightly this year.', 'en-GB', 'What has happened to youth unemployment?', ['It has risen', 'It has fallen a little', 'It has doubled', 'It has not changed'], 1, 'Fallen slightly = è calata un poco.'),
      mc('Which sentence is correct?', ['The government will raise taxes.', 'The government will rise taxes.', 'The government will arise taxes.', 'The government will rose taxes.'], 0)
    ],
    test: [
      mc('Which phrase is correct?', ['an economical recession in Europe', 'a serious economic recession in Europe', 'a economy recession in Europe', 'an economics recession in Europe'], 1),
      mc('«Welfare» refers to…', ['support from the state for people in need', 'a type of tax on companies', 'a bank loan', 'rules for traffic'], 0),
      mc('«An ageing population» means…', ['more old people in the country', 'a rise in births', 'young migrants', 'a fall in life expectancy'], 0),
      mc('Which is correct?', ['The unemployment is a serious problem.', 'Unemployment is a serious problem.', 'An unemployment are a serious problem.', 'Unemployments are a serious problem.'], 1),
      fill('Complete: Prices ___ by 3% last year. (aumentare, passato: rose/raised)', ['rose'], 'Rise è intransitivo: rose.')
    ],
    cards: [card('c1', 'economia', 'economy', 'a strong economy'), card('c2', 'crescita', 'growth', 'economic growth'), card('c3', 'disoccupazione', 'unemployment', 'high unemployment'), card('c4', 'disuguaglianza', 'inequality', 'social inequality'),
      card('c5', 'tassa/imposte', 'tax', 'raise taxes'), card('c6', 'reddito', 'income', 'a low income'), card('c7', 'popolazione', 'population', 'an ageing population'), card('c8', 'sussidi', 'benefits', 'unemployment benefits'), card('c9', 'povertà', 'poverty', 'live in poverty'), card('c10', 'permettersi', 'to afford', 'I can’t afford it.')],
    listening: [{ id: 'l1', lang: 'en-GB', title: 'Radio discussion', text: 'Over the last ten years the cost of living has risen steadily, while wages have barely moved. As a result, the gap between rich and poor is growing, and many young people can’t afford to rent a flat. The government says it will build more affordable housing, but critics argue that this is not enough. They want a higher minimum wage and better public services. Personally, I think both measures are needed. Of course, they would cost money, and taxes might have to go up.',
      qs: [{ q: 'What has happened to the cost of living?', o: ['It has risen steadily', 'It has fallen sharply', 'It has not changed', 'It has doubled overnight'], a: 0, kind: 'explicit' }, { q: 'What do the critics want?', o: ['A higher minimum wage and better services', 'Lower taxes', 'Fewer immigrants', 'More private housing only'], a: 0, kind: 'explicit' }, { q: 'What is the speaker’s opinion?', o: ['Both measures are needed, but they are costly', 'None of the measures will work', 'Only housing matters', 'Taxes must fall'], a: 0, kind: 'implicit' }] }],
    dictation: [{ text: 'Unemployment has risen sharply since the recession.', lang: 'en-GB' }, { text: 'Many young people can’t afford to buy a house.', lang: 'en-US' }, { text: 'The government plans to raise taxes next year.', lang: 'en-AU' }],
    shadowing: [{ text: 'The gap between rich and poor is growing.', lang: 'en-GB', tip: 'Accento su gap, rich, poor, growing.' }, { text: 'Unemployment has fallen slightly this year.', lang: 'en-US', tip: 'unemPLOYment: accento sulla seconda sillaba.' }, { text: 'The government should create more jobs.', lang: 'en-AU', tip: 'GOVernment: la n spesso si perde nel parlato veloce.' }],
    speaking: [{ prompt: 'Give your opinion on one social problem in your country (e.g. unemployment, housing) and suggest one solution.', model: 'In my view, youth unemployment is a major problem. The government should create more apprenticeships, and companies should offer more training. In the long run, this would boost the economy.' }, { prompt: 'Describe a change in the cost of living or in prices in your town.', model: 'Prices have increased steadily over the last five years, especially rent. As a result, many young people live with their parents for longer.' }] });

  T({ id: 'eng-l3-vocab-science-technology', stage: 'L3', prereq: ['eng-l2-word-formation'], title: 'Lessico B2: scienza e tecnologia', summary: 'Ricerca, scoperte, dispositivi, ambiente e dibattiti etici: parole, collocazioni e formule per parlarne.',
    objectives: ['Parlare di ricerca, scoperte e innovazione con precisione', 'Usare il lessico di tecnologia digitale e ambiente', 'Esprimere vantaggi, rischi e opinioni su temi scientifici'],
    pages: [
      { h: 'Obiettivo', b: 'Scienza e tecnologia sono temi ricorrenti negli esami B2 (ascolti, lettura, saggi). Servono **parole specifiche**, ma anche **verbi e preposizioni** corretti (*a breakthrough in*, *advances in*). Questa lezione offre un lessico di base e frasi per discuterne.' },
      { h: 'Ricerca e scoperte', b: '- **research** (non numerabile!), **study**, **experiment**, **findings** = risultati, **evidence** (non numerabile), **data**\n- **theory** (teoria), **hypothesis** (ipotesi), **breakthrough** = svolta\n- **invent** (creare qualcosa di nuovo: *the telephone*) / **discover** (trovare qualcosa che già esisteva: *penicillin*)\n- **develop**, **analyse**, **test**, **prove**, **conclude**\n\n{{en-GB|A recent study found that sleep improves memory.}}\n{{en-GB|The researchers carried out an experiment on 200 volunteers.}}\n\nAttenzione: **experience** (esperienza) ≠ **experiment** (esperimento).' },
      { h: 'Tecnologia digitale', b: '- **device** = dispositivo; **gadget**; **software / hardware**; **app**; **network**\n- **download / upload**; **log in / log out**; **back up** your files\n- **search engine**; **social media**; **online privacy**; **data protection**; **hack**\n- **cutting-edge / state-of-the-art** = all’avanguardia\n- **be addicted to** (dipendente da): {{en-GB|Many teenagers are addicted to their phones.}}\n\n**Technology** è non numerabile (*modern technology*); *a technology* esiste ma indica una specifica tecnologia.' },
      { h: 'Ambiente e energia', b: '- **climate change**, **global warming**, **greenhouse gases**, **emissions**\n- **renewable energy** (solar, wind), **fossil fuels**, **pollution**, **waste**, **recycling**\n- **sustainable** = sostenibile; **environmentally friendly**\n- **reduce / cut** emissions; **switch to** renewable energy; **protect** the environment.\n\n{{en-GB|Many countries are switching to renewable energy to cut emissions.}}\n\nCollocazioni: **a breakthrough in** (+ campo), **advances in** medicine, **progress in** research, **a danger to** the environment.' },
      { h: 'Vantaggi, rischi, opinioni', b: 'Per bilanciare un argomento:\n- {{en-GB|One major advantage of this technology is that it saves time.}}\n- {{en-GB|However, there are serious concerns about privacy.}}\n- {{en-GB|Critics argue that robots may replace many workers.}}\n- {{en-GB|On balance, the benefits outweigh the risks.}}\n- {{en-GB|It remains to be seen whether…}}\n\n**Concern** = preoccupazione; **outweigh** = pesare più di; **ethical** = etico; **risk** = rischio.' },
      { h: 'Esempio guidato', b: 'Idea: *«Uno studio recente mostra che l’energia solare è sempre più economica. Ci sono vantaggi ma anche dubbi sul costo iniziale.»*\n\n→ **A recent study shows that solar energy is becoming cheaper. There are clear advantages, but some people are concerned about the initial cost.**\n\nControllo: *a study shows*, *becoming cheaper*, *concerned about*.' },
      { h: 'Errori comuni', b: '- *a research* / *researches* → {{en-GB|some research / a piece of research.}}\n- *an evidence* → {{en-GB|some evidence.}}\n- *The data is / are*: nel B2 sono accettati entrambi; con *data* come massa si usa *is*.\n- *invent a new planet* → {{en-GB|discover a planet.}}\n- *experience* per «esperimento» → {{en-GB|experiment.}}\n- *dependent of* → {{en-GB|dependent on.}}\n- *an advance of medicine* → {{en-GB|an advance in medicine.}}' },
      { h: 'Riepilogo', b: '- research / evidence / technology: non numerabili.\n- invent (creare) vs discover (trovare).\n- findings, hypothesis, breakthrough in, advances in.\n- device, download, privacy, cutting-edge.\n- renewable energy, emissions, sustainable.\n- Vantaggio + preoccupazione + «on balance».' }
    ],
    exercises: [
      mc('Alexander Fleming ___ penicillin in 1928.', ['invented', 'discovered', 'researched', 'developed on'], 1, 'Discover = trovare ciò che già esiste.'),
      mc('Which sentence is correct?', ['She did a lot of researches.', 'She did a lot of research.', 'She did a lot of a research.', 'She did many researches.'], 1),
      mc('A big, sudden improvement in knowledge is a…', ['finding', 'device', 'breakthrough', 'hypothesis'], 2),
      fill('Complete: There have been great advances ___ medicine. (preposizione)', ['in'], 'Advances in + campo.'),
      mc('Wind and solar are examples of ___ energy.', ['fossil', 'renewable', 'nuclear only', 'dirty'], 1),
      order('Metti in ordine', ['The', 'benefits', 'outweigh', 'the', 'risks'], 'Outweigh = pesare più di.'),
      listen('Researchers have developed a battery that charges in five minutes.', 'en-US', 'What have the researchers developed?', ['A fast-charging battery', 'A new planet', 'A medicine', 'A faster plane'], 0, 'A fast-charging battery.'),
      mc('If you cannot stop using your phone, you may be…', ['addicted to it', 'addicted of it', 'addicted for it', 'addicted at it'], 0)
    ],
    test: [
      mc('Which word is NOT countable?', ['device', 'evidence', 'experiment', 'study'], 1),
      mc('«Cutting-edge technology» is…', ['very old', 'very advanced', 'cheap', 'dangerous'], 1),
      mc('The Italian «esperimento» is…', ['experience', 'experiment', 'expert', 'experimental only'], 1),
      mc('Choose the correct sentence.', ['A study found that sleep improves memory.', 'A study found what sleep improves memory.', 'A study have found that sleep improves memory.', 'A study find that sleep improves memory.'], 0),
      fill('Complete: Many countries are switching ___ renewable energy. (preposizione)', ['to'], 'Switch to.')
    ],
    cards: [card('c1', 'ricerca', 'research', 'medical research'), card('c2', 'scoperta/svolta', 'breakthrough', 'a major breakthrough'), card('c3', 'dispositivo', 'device', 'a mobile device'), card('c4', 'risultati', 'findings', 'the findings of the study'),
      card('c5', 'prova (scientifica)', 'evidence', 'There’s no evidence.'), card('c6', 'rinnovabile', 'renewable', 'renewable energy'), card('c7', 'emissioni', 'emissions', 'carbon emissions'), card('c8', 'sostenibile', 'sustainable', 'sustainable travel'), card('c9', 'inventare', 'to invent', 'He invented a machine.'), card('c10', 'scoprire', 'to discover', 'They discovered a new species.')],
    listening: [{ id: 'l1', lang: 'en-AU', title: 'A science podcast', text: 'Welcome to the programme. Today we’re talking about a recent breakthrough in solar technology. Researchers at an Australian university have developed a new type of panel that produces more energy and costs less. The findings were published last week. Of course, there are some concerns: the panels are still expensive to produce, and recycling them is difficult. Nevertheless, most experts agree that renewable energy is the future, and this discovery is an important step forward.',
      qs: [{ q: 'What have the researchers developed?', o: ['A new type of solar panel', 'A wind turbine', 'A new battery', 'A nuclear reactor'], a: 0, kind: 'explicit' }, { q: 'What is one concern?', o: ['The panels are costly to produce', 'The panels cause pollution', 'The panels don’t work in Australia', 'The study was published too late'], a: 0, kind: 'explicit' }, { q: 'What is the presenter’s general attitude?', o: ['Optimistic, with some caution', 'Completely against it', 'Bored', 'Not interested'], a: 0, kind: 'implicit' }] }],
    dictation: [{ text: 'A recent study found that sleep improves memory.', lang: 'en-GB' }, { text: 'Many countries are switching to renewable energy.', lang: 'en-US' }, { text: 'The benefits outweigh the risks.', lang: 'en-AU' }],
    shadowing: [{ text: 'Researchers have made an important breakthrough.', lang: 'en-GB', tip: 'reSEARCHers e BREAKthrough: accenti principali.' }, { text: 'There are serious concerns about privacy.', lang: 'en-US', tip: 'PRIvacy (US) / PRIVacy (UK): due varianti.' }, { text: 'Technology has changed the way we live.', lang: 'en-AU', tip: 'techNOlogy: accento sulla seconda sillaba.' }],
    speaking: [{ prompt: 'Talk about one technology you use every day: one advantage and one risk.', model: 'I use my smartphone every day. One major advantage is that I can find any information quickly. However, there are concerns about privacy, and many people are addicted to their phones.' }, { prompt: 'Give your opinion about renewable energy.', model: 'In my opinion, renewable energy is essential. It helps cut emissions and protects the environment. On balance, I think the benefits outweigh the costs.' }] });

  /* ---------- L4 ---------- */
  T({ id: 'eng-l4-discourse-markers-writing', stage: 'L4', prereq: ['eng-l3-essay-writing'], title: 'Connettori di discorso per la scrittura: however, whereas, nevertheless', summary: 'Aggiunta, contrasto, concessione, causa e conclusione: significato, posizione e punteggiatura dei connettori formali.',
    objectives: ['Scegliere il connettore giusto per contrasto, concessione, aggiunta, causa e conclusione', 'Collocarli correttamente nella frase con la punteggiatura giusta', 'Evitare errori tipici (in the contrary, besides of, despite of)'],
    pages: [
      { h: 'Obiettivo', b: 'In un testo B2 i **connettori di discorso** (discourse markers) mostrano come le idee si collegano. Ogni connettore ha un **significato**, una **posizione** e una **punteggiatura** specifici. Scegliere bene alza il registro e la coerenza di un saggio o di una relazione.' },
      { h: 'Contrasto: however, whereas, in contrast', b: '- **however** (nuova frase, virgola dopo; anche dopo punto e virgola): {{en-GB|Prices have risen. However, wages have stayed the same.}} / {{en-GB|Prices have risen; however, wages have stayed the same.}}\n- **whereas / while** (dentro la frase; mette a confronto due cose): {{en-GB|Some people prefer cities, whereas others prefer the countryside.}}\n- **in contrast / by contrast / on the other hand**: {{en-GB|Cities are noisy. In contrast, villages are quiet.}}\n- **on the contrary** = al contrario, nega un’idea precedente: {{en-GB|The film wasn’t boring. On the contrary, it was fascinating.}}\n\nNon si scrive *in the contrary* e non si inizia con *but* in un testo formale.' },
      { h: 'Concessione: nevertheless, nonetheless, although', b: 'Introducono un elemento che **contrasta con l’aspettativa**:\n- **nevertheless / nonetheless** = ciononostante (come *however*, più formali): {{en-GB|The plan was risky. Nevertheless, they went ahead.}}\n- **although / even though / though** + frase: {{en-GB|Although the plan was risky, they went ahead.}}\n- **despite / in spite of** + nome o -ing: {{en-GB|Despite the risk, they went ahead.}}\n- **admittedly** = è vero che: {{en-GB|Admittedly, the course is expensive; however, it is excellent.}}\n- **all the same, still, even so**: più informali.\n\nUn solo connettore di contrasto per frase: *Although … but* non va bene.' },
      { h: 'Aggiunta e rinforzo', b: '- **moreover, furthermore, in addition, what is more** (formali): {{en-GB|The scheme is cheap. Moreover, it is easy to use.}}\n- **besides** = inoltre/per di più (informale): {{en-GB|I’m too tired to go out. Besides, it’s late.}}\n- **as well as** + nome/-ing: {{en-GB|As well as being cheap, it is fast.}}\n- **not only … but also**: {{en-GB|It is not only cheap but also fast.}}\n\n*Besides* ≠ *beside* (accanto a). E non *besides of*.' },
      { h: 'Causa e conseguenza', b: '- **because of / due to / owing to** + nome: {{en-GB|The flight was cancelled due to bad weather.}}\n- **since / as** = poiché (causa nota): {{en-GB|Since it was raining, we stayed in.}}\n- **therefore, consequently, as a result, thus** = quindi: {{en-GB|Sales fell. Consequently, the company closed two shops.}}\n- **so** = informale: *Sales fell, so the company closed two shops.*\n\nPosizione: *therefore* può stare a inizio frase (con virgola) o dopo il soggetto: *The company therefore decided to…*.' },
      { h: 'Struttura del testo', b: '- Inizio: **firstly, to begin with, in the first place**\n- Seguito: **secondly, in addition, next, then**\n- Esempio: **for example, for instance, such as**\n- Concludere: **finally, in conclusion, to sum up, overall**\n- Differenza: **at the end** (alla fine di qualcosa) / **in the end** (infine, alla fine di un processo).\n\n{{en-GB|In conclusion, the advantages of the scheme outweigh the disadvantages.}}\n\nNon abusare: 3–4 connettori ben scelti per paragrafo bastano.' },
      { h: 'Esempio guidato', b: 'Unisci: *«Il lavoro da remoto fa risparmiare tempo. Può isolare le persone. La produttività è alta.»*\n\n→ **Remote work saves time and, moreover, productivity is high. However, it can leave employees isolated. Overall, its advantages seem to outweigh its drawbacks.**\n\nControllo: aggiunta (moreover), contrasto (however), conclusione (overall).' },
      { h: 'Errori comuni', b: '- *In the contrary* → {{en-GB|On the contrary.}}\n- *Despite of the rain* → {{en-GB|Despite the rain.}}\n- *Although it was late, but we continued.* → {{en-GB|Although it was late, we continued.}}\n- *However, but…* → solo uno dei due.\n- *Besides of that* → {{en-GB|Besides that.}}\n- *At the end I decided to go.* (infine) → {{en-GB|In the end I decided to go.}}\n- *Moreover* in apertura di un testo: non ha un’idea precedente da aggiungere.\n- Due frasi unite da *however* con la sola virgola: {{en-GB|…; however, …}} oppure punto.' },
      { h: 'Riepilogo', b: '- Contrasto: however, whereas, in contrast, on the other hand.\n- Concessione: nevertheless, although, despite + nome/-ing.\n- Aggiunta: moreover, furthermore, in addition, besides.\n- Causa/conseguenza: due to, since, therefore, as a result.\n- Chiusura: finally, in conclusion, overall.' }
    ],
    exercises: [
      mc('Some people love winter, ___ others prefer summer.', ['however', 'whereas', 'despite', 'so'], 1),
      mc('The plan was risky. ___, they went ahead.', ['Besides', 'Therefore', 'Nevertheless', 'Because'], 2),
      mc('The film wasn’t boring. ___, it was fascinating.', ['On the contrary', 'In the contrary', 'At the contrary', 'By the contrary'], 0),
      fill('Complete: The flight was cancelled ___ to bad weather. (a causa di)', ['due', 'owing'], 'Due to / owing to + nome.'),
      mc('Which sentence is correct?', ['Despite of the rain, we went out.', 'Despite the rain, we went out.', 'Although the rain, we went out.', 'In despite the rain, we went out.'], 1),
      order('Metti in ordine', ['Sales', 'fell;', 'consequently,', 'prices', 'were', 'cut'], 'Consequently = di conseguenza.'),
      listen('The course is expensive. Admittedly, it is well organised; however, many students cannot afford it.', 'en-GB', 'What is the main problem mentioned?', ['The course is badly organised', 'Many cannot afford it', 'The course is too long', 'The teachers are rude'], 1, 'Dopo however c’è il punto chiave.'),
      mc('«To sum up» is used…', ['to begin an essay', 'to add an example', 'to conclude', 'to contrast ideas'], 2)
    ],
    test: [
      mc('Which sentence uses the connector correctly?', ['Although it was late, but we kept working.', 'It was late; nevertheless, we kept working.', 'It was late despite we kept working.', 'It was late, however but we kept working.'], 1),
      mc('«Furthermore» is closest to…', ['however', 'in addition', 'in contrast', 'despite'], 1),
      mc('Choose the best word: «Cities are noisy and crowded. ___, villages are quiet and calm.»', ['In contrast', 'Therefore', 'Moreover', 'As a result'], 0),
      mc('Which is correct?', ['He lost his job. At the end, he moved abroad.', 'He lost his job. In the end, he moved abroad.', 'He lost his job. In the contrary, he moved abroad.', 'He lost his job. Beside, he moved abroad.'], 1),
      fill('Complete: As a ___, the company closed two shops. (conseguenza)', ['result'], 'As a result.')
    ],
    cards: [card('c1', 'tuttavia', 'however', 'However, I disagree.'), card('c2', 'mentre (contrasto)', 'whereas', 'Tom likes tea, whereas Ann likes coffee.'), card('c3', 'ciononostante', 'nevertheless', 'Nevertheless, we continued.'), card('c4', 'al contrario', 'on the contrary', 'On the contrary, it was great.'),
      card('c5', 'inoltre', 'moreover', 'Moreover, it is cheap.'), card('c6', 'di conseguenza', 'consequently', 'Consequently, we left.'), card('c7', 'a causa di', 'due to', 'due to the rain'), card('c8', 'è vero che', 'admittedly', 'Admittedly, it is hard.'), card('c9', 'in conclusione', 'in conclusion', 'In conclusion, it works.'), card('c10', 'per esempio', 'for instance', 'For instance, in Italy…')],
    listening: [{ id: 'l1', lang: 'en-GB', title: 'A student presentation', text: 'Today I’d like to talk about remote work. Firstly, it saves time, because employees don’t have to commute. Moreover, many companies save money on office space. However, there are some disadvantages. Whereas some workers enjoy the freedom, others feel isolated. Nevertheless, most surveys show that people want to keep some flexibility. In conclusion, I believe a mixture of home and office work is the best solution.',
      qs: [{ q: 'What is the first advantage mentioned?', o: ['It saves commuting time', 'It increases salaries', 'It gives longer holidays', 'It reduces taxes'], a: 0, kind: 'explicit' }, { q: 'What disadvantage is mentioned?', o: ['Some people feel isolated', 'Work is too easy', 'Computers cost a lot', 'Bosses are angry'], a: 0, kind: 'explicit' }, { q: 'What is the speaker’s final view?', o: ['A mix of home and office work', 'Everyone should work at home', 'Everyone should work in the office', 'Remote work should be banned'], a: 0, kind: 'implicit' }] }],
    dictation: [{ text: 'Prices have risen; however, wages have stayed the same.', lang: 'en-GB' }, { text: 'Some people prefer cities, whereas others prefer the countryside.', lang: 'en-US' }, { text: 'Nevertheless, most experts agree with the plan.', lang: 'en-AU' }],
    shadowing: [{ text: 'However, there are some disadvantages.', lang: 'en-GB', tip: 'Pausa dopo however; tono discendente-ascendente.' }, { text: 'In conclusion, the benefits outweigh the costs.', lang: 'en-US', tip: 'inconCLUsion: accento sulla seconda sillaba di conclusion.' }, { text: 'Nevertheless, we decided to continue.', lang: 'en-AU', tip: 'neverTHEless: accento sulla terza sillaba.' }],
    speaking: [{ prompt: 'Compare two cities or two ways of living using whereas and in contrast.', model: 'City life is exciting and full of opportunities, whereas country life is calm and healthy. In contrast to the city, the village offers fresh air, but it has fewer jobs.' }, { prompt: 'Give a short opinion with admittedly and nevertheless.', model: 'Admittedly, public transport is sometimes late. Nevertheless, I prefer it to driving, because it is cheaper and better for the environment.' }] });

  T({ id: 'eng-l4-error-correction-b2', stage: 'L4', prereq: ['eng-l3-essay-writing'], title: 'Autocorrezione B2: tempi, accordo, articoli, ordine delle parole', summary: 'Gli errori tipici da B2 e come individuarli e correggerli: esercizi di correzione con lista di controllo.',
    objectives: ['Riconoscere errori frequenti di tempi, accordo, articoli e ordine delle parole', 'Correggere frasi sbagliate spiegando la regola', 'Rileggere un testo con una lista di controllo'],
    pages: [
      { h: 'Obiettivo', b: 'A B2 la comunicazione funziona, ma restano errori **fossilizzati** che compaiono sempre negli stessi punti. Imparare a **rileggere e correggere** è una competenza d’esame (scrittura, uso dell’inglese) e un’abitudine per migliorare. Qui trovi gli errori tipici con la correzione.' },
      { h: 'Tempi verbali', b: '- *I live here since 2019.* → {{en-GB|I have lived here since 2019.}} (stato iniziato nel passato e ancora vero)\n- *I have seen him yesterday.* → {{en-GB|I saw him yesterday.}} (tempo concluso = past simple)\n- *When I will arrive, I will call you.* → {{en-GB|When I arrive, I’ll call you.}} (dopo when/if/as soon as niente will)\n- *If I would have time, I would help.* → {{en-GB|If I had time, I would help.}}\n- *I’m knowing him.* → {{en-GB|I know him.}} (verbi di stato senza -ing)\n- *She said me that…* → {{en-GB|She told me that…}}' },
      { h: 'Accordo soggetto-verbo', b: '- *He don’t like it.* → {{en-GB|He doesn’t like it.}}\n- *The news are bad.* → {{en-GB|The news is bad.}} (non numerabile)\n- *People is angry.* → {{en-GB|People are angry.}}\n- *Everybody have a ticket.* → {{en-GB|Everybody has a ticket.}} (singolare)\n- *A number of students was late.* → {{en-GB|A number of students were late.}} / *The number of students is small.*\n- *One of my friends live in Rome.* → {{en-GB|One of my friends lives in Rome.}}\n\nControlla il vero **soggetto**, non il nome più vicino al verbo.' },
      { h: 'Articoli e quantità', b: '- *I like the pizza.* (in generale) → {{en-GB|I like pizza.}}\n- *She is doctor.* → {{en-GB|She is a doctor.}}\n- *It’s the best of the world.* → {{en-GB|It’s the best in the world.}}\n- *I bought an interesting book. A book was about…* → {{en-GB|The book was about…}} (seconda menzione)\n- *I have a lot of homeworks.* → {{en-GB|a lot of homework.}}\n- *much people* → {{en-GB|many people.}}\n\nDomanda di controllo: **numerabile o no? Già noto o nuovo? Generale o specifico?**' },
      { h: 'Ordine delle parole', b: '- *I drink always tea.* → {{en-GB|I always drink tea.}} (avverbi di frequenza prima del verbo, dopo *be*)\n- *I like very much music.* → {{en-GB|I like music very much.}}\n- *I don’t know where is the station.* → {{en-GB|I don’t know where the station is.}} (domanda indiretta = ordine affermativo)\n- *Yesterday I went at the cinema with my friends.* → {{en-GB|I went to the cinema with my friends yesterday.}}\n- *He asked me what did I want.* → {{en-GB|He asked me what I wanted.}}\n\nSchema base: **Soggetto – Verbo – Oggetto – Luogo – Tempo**.' },
      { h: 'Lista di controllo per rileggere', b: 'Rileggi il testo **quattro volte**, una per ogni tipo di errore:\n1. **Verbi**: tempo giusto? *-s* alla terza persona? ausiliari?\n2. **Nomi**: numerabile/non numerabile? plurali? articoli?\n3. **Ordine**: soggetto-verbo-oggetto? avverbi? domande indirette?\n4. **Preposizioni e parole**: *depend on*, *interested in*, false friends?\n\nCorreggi solo ciò che sai spiegare. Se non sei sicuro, riformula con una frase più semplice.' },
      { h: 'Esempio guidato', b: 'Correggi: *«Yesterday I have seen a film. The film were very interesting and the people in it was funny. I like very much films about the life.»*\n\n→ **Yesterday I saw a film. The film was very interesting and the people in it were funny. I like films about life very much.**\n\nControllo: past simple, accordo *film was*, *people were*, ordine *like … very much*, *life* senza articolo.' },
      { h: 'Errori comuni', b: '- Correggere sempre «a occhio» invece di controllare una categoria alla volta.\n- Dimenticare la **-s** della terza persona (*she works*).\n- Mettere *will* dopo *when / if*.\n- Tradurre le domande indirette con l’ordine delle domande dirette.\n- Usare *the* per concetti generali (*the life, the music*).\n- Introdurre **nuovi errori** correggendo in fretta.' },
      { h: 'Riepilogo', b: '- Tempi: have lived since; saw yesterday; when I arrive.\n- Accordo: he doesn’t; the news is; people are; everybody has.\n- Articoli: pizza (generale), a doctor, the best in the world.\n- Ordine: I always drink; I like it very much; where the station is.\n- Rileggi con una lista di controllo: verbi, nomi, ordine, preposizioni.' }
    ],
    exercises: [
      mc('Which sentence is correct?', ['I live here since 2019.', 'I have lived here since 2019.', 'I am living here since 2019.', 'I lived here since 2019.'], 1),
      mc('Which sentence is correct?', ['He don’t like coffee.', 'He doesn’t likes coffee.', 'He doesn’t like coffee.', 'He not like coffee.'], 2),
      mc('Which sentence is correct?', ['I don’t know where is the station.', 'I don’t know where the station is.', 'I don’t know where does the station is.', 'I don’t know where the station does.'], 1),
      fill('Complete: When I ___ (arrive), I’ll call you.', ['arrive', 'get', 'get there'], 'Dopo when niente will: presente.'),
      mc('Correct the sentence: «She is doctor.»', ['She is the doctor.', 'She is a doctor.', 'She is doctors.', 'She is an doctor.'], 1),
      order('Metti in ordine', ['I', 'always', 'drink', 'tea', 'in', 'the', 'morning'], 'Avverbio di frequenza prima del verbo.'),
      listen('The news was surprising, and everybody has already heard it.', 'en-GB', 'What is true about the news?', ['It was surprising and known by everyone', 'It was boring', 'Nobody has heard it', 'It was bad'], 0, 'News singolare; everybody has.'),
      mc('Which sentence is correct?', ['Everybody have a ticket.', 'Everybody has a ticket.', 'Everybody are having a ticket.', 'Everybody do have a ticket.'], 1)
    ],
    test: [
      mc('Which is correct?', ['I have seen him yesterday.', 'I saw him yesterday.', 'I have saw him yesterday.', 'I was seeing him yesterday.'], 1),
      mc('Which is correct?', ['If I would have time, I would come.', 'If I had time, I would come.', 'If I have had time, I would come.', 'If I will have time, I would come.'], 1),
      mc('Which sentence has the correct word order?', ['I like very much jazz.', 'I like jazz very much.', 'Very much I like jazz.', 'I very much like it jazz.'], 1),
      mc('Choose the correct sentence.', ['He asked me what did I want.', 'He asked me what I wanted.', 'He asked me what I did want?', 'He asked me what wanted I.'], 1),
      fill('Complete: The news ___ bad today. (is/are)', ['is'], 'News è singolare.')
    ],
    cards: [card('c1', 'errore', 'mistake', 'a common mistake'), card('c2', 'correggere', 'to correct', 'Please correct the sentences.'), card('c3', 'accordo (grammaticale)', 'agreement', 'subject-verb agreement'), card('c4', 'ordine delle parole', 'word order', 'English word order is fixed.'),
      card('c5', 'rileggere', 'to proofread', 'Proofread your essay.'), card('c6', 'lista di controllo', 'checklist', 'a writing checklist'), card('c7', 'autocorreggersi', 'to self-correct', 'He can self-correct quickly.'), card('c8', 'articolo', 'article', 'a, an and the are articles'), card('c9', 'non numerabile', 'uncountable', 'an uncountable noun'), card('c10', 'domanda indiretta', 'indirect question', 'an indirect question')],
    listening: [{ id: 'l1', lang: 'en-AU', title: 'Advice from a teacher', text: 'When you finish an essay, don’t hand it in immediately. Read it four times. First, check the verbs: are the tenses right, and did you add the s in the third person? Then look at the nouns: is it uncountable, and do you need an article? Next, check the word order, especially in indirect questions. Finally, check prepositions and false friends. Honestly, most of my students make the same ten mistakes, and they could correct them easily if they only took five minutes.',
      qs: [{ q: 'How many times should students read the essay?', o: ['Four', 'Once', 'Ten', 'Two'], a: 0, kind: 'explicit' }, { q: 'What should students check first?', o: ['Verbs', 'Prepositions', 'Spelling only', 'Handwriting'], a: 0, kind: 'explicit' }, { q: 'What does the teacher imply about students’ mistakes?', o: ['They are often avoidable', 'They are impossible to fix', 'They only happen at B1', 'They don’t matter'], a: 0, kind: 'implicit' }] }],
    dictation: [{ text: 'When I arrive, I will call you.', lang: 'en-GB' }, { text: 'I don’t know where the station is.', lang: 'en-US' }, { text: 'Everybody has already heard the news.', lang: 'en-AU' }],
    shadowing: [{ text: 'I always drink tea in the morning.', lang: 'en-GB', tip: 'alWAYS: accento sulla seconda sillaba di always.' }, { text: 'He doesn’t like coffee, but he loves tea.', lang: 'en-US', tip: 'Doesn’t /ˈdʌznt/: nasale finale.' }, { text: 'She asked me what I wanted.', lang: 'en-AU', tip: 'Ordine affermativo in domanda indiretta.' }],
    speaking: [{ prompt: 'Say the corrected version of: «Yesterday I have seen a film and the people was funny.»', model: 'Yesterday I saw a film, and the people were funny.' }, { prompt: 'Explain two mistakes you often make in English and how you check them.', model: 'I often forget the s in the third person, and I put adverbs in the wrong place. When I write, I read my text twice and check the verbs first.' }] });

})(window.ST = window.ST || {});
